"""D採用前の短時間合成制御測定。自然音声/MOS/テストを追加しない。"""
import os
for k in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS'): os.environ[k]='1'
from pathlib import Path
import sys, json, hashlib, importlib.util, importlib, traceback, datetime, platform
from dataclasses import replace
import numpy as np
ROOT=Path(__file__).resolve().parent/'vocoder'
sys.path.insert(0,str(ROOT))
from vocoderbench import hnm_control as control, hnm_synthesis as base
OUT=ROOT/'runs/adoption-controls-synthetic'
OUT.mkdir(parents=True,exist_ok=True)
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def ah(a): return hashlib.sha256(np.ascontiguousarray(a).tobytes()).hexdigest()
pkg=ROOT.parent/'noise_candidates/D'
spec=importlib.util.spec_from_file_location('_adoption_D',pkg/'__init__.py',submodule_search_locations=[str(pkg)])
m=importlib.util.module_from_spec(spec);sys.modules[spec.name]=m;spec.loader.exec_module(m)
d=importlib.import_module('_adoption_D.hnm_synthesis')
source=Path(__file__).read_bytes().decode('utf-8')
contract={'script_sha256':sha(__file__),'script_text':source,'baseline_files':{p.name:sha(p) for p in (ROOT/'vocoderbench').glob('hnm*.py')},'candidate_files':{p.name:sha(p) for p in pkg.glob('*.py')},'python':platform.python_version(),'numpy':np.__version__,'seeds':list(range(8)),'sample_rate':16000,'duration':0.5,'planned_outputs':192,'scope':'_noise only; harmonic synthesis unchanged; no MOS','criteria':{'finite':True,'length':'exact parameter n_samples','silence':'exact zero where interpolated target power is zero','gain_relative_max_error':1e-12,'pitch_noise_max_error':0.0,'normalized_analytic_expected_power_absolute_error':1e-12,'empirical_power':'descriptive only; eight seeds do not guarantee convergence, especially narrow bands'}}
(OUT/'contract.json').write_text(json.dumps(contract,ensure_ascii=False,indent=2),encoding='utf-8')
p=control.make_synthetic_parameters(f0_hz=140,duration=.5,noise_fraction=1)
flat=p; grid=p.frequency_grid
cases={'zero_noise':replace(p,noise_psd=np.zeros_like(p.noise_psd)),'flat':p}
for name,shape in [('dc_concentrated',np.exp(-grid/80)),('nyquist_concentrated',np.exp(-(8000-grid)/80))]:
 shape=shape/np.trapezoid(shape,grid)*np.trapezoid(p.noise_psd[0],grid)
 cases[name]=replace(p,noise_psd=np.tile(shape,(len(p.frame_times),1)))
for name,mask in [('sound_to_silence',p.frame_times<.25),('short_burst',(p.frame_times>=.245)&(p.frame_times<=.255))]:
 cases[name]=replace(p,noise_psd=p.noise_psd*mask[:,None])
for name,kwargs in [('gain_minus6',{'gain_db':-6}),('gain_plus6',{'gain_db':6}),('time_half',{'time_scale':.5}),('time_double',{'time_scale':2}),('pitch_minus12',{'pitch_semitones':-12}),('pitch_plus12',{'pitch_semitones':12})]: cases[name]=control.edit_parameters(p,**kwargs)
rows=[]; waves={}; analytic=[]
for name,q in cases.items():
 powers=np.trapezoid(q.noise_psd,q.frequency_grid,axis=1)
 target=np.interp(np.arange(q.n_samples)/q.sample_rate,q.frame_times,powers)
 for method,module in [('v2',base),('D',d)]:
  active=np.flatnonzero(powers>0)
  if len(active):
   nfft=512; fftgrid=np.fft.rfftfreq(nfft,1/q.sample_rate);df=q.sample_rate/nfft
   psd=np.interp(fftgrid,q.frequency_grid,q.noise_psd[active[0]]/powers[active[0]])
   endweight=1 if method=='v2' else .5
   den=df*(psd[1:-1].sum()+endweight*(psd[0]+psd[-1]));norm=psd/den
   # Parseval: endpoint variances + twice interior complex energies, divided by N^2.
   endpoint_var=endweight*norm[[0,-1]]*q.sample_rate*nfft
   interior_complex_energy=norm[1:-1]*q.sample_rate*nfft/2
   expected=float((endpoint_var.sum()+2*interior_complex_energy.sum())/nfft**2)
   analytic.append({'case':name,'method':method,'normalized_expected_power':expected,'absolute_error':abs(expected-1),'endpoint_expected_power_fraction':float(endpoint_var.sum()/nfft**2),'target_power_mean':float(target.mean())})
  for seed in range(8):
   row={'case':name,'method':method,'seed':seed}
   try:
    y=module._noise(q,seed);waves[(name,method,seed)]=y
    spectrum=np.abs(np.fft.rfft(y))**2;freq=np.fft.rfftfreq(len(y),1/q.sample_rate);total=float(spectrum.sum())
    row.update(status='measured',waveform_float64_sha256=ah(y),n_samples=len(y),expected_n_samples=q.n_samples,finite=bool(np.isfinite(y).all()),peak=float(np.max(np.abs(y))),power=float(np.mean(y*y)),target_power_mean=float(target.mean()),power_ratio=float(np.mean(y*y)/target.mean()) if target.mean()>0 else None,zero_target_samples=int((target==0).sum()),zero_target_max_abs=float(np.max(np.abs(y[target==0]))) if np.any(target==0) else None,low_200hz_energy_fraction=float(spectrum[freq<200].sum()/total) if total else None,high_7800hz_energy_fraction=float(spectrum[freq>7800].sum()/total) if total else None)
    if name.startswith('gain_'):
     gain=10**((-6 if name=='gain_minus6' else 6)/20);reference=waves[('flat',method,seed)]*gain
     row['gain_relative_max_error']=float(np.max(np.abs(y-reference))/max(np.max(np.abs(reference)),1e-30))
    if name.startswith('pitch_'): row['pitch_noise_max_error']=float(np.max(np.abs(y-waves[('flat',method,seed)])))
    row['criteria_pass']=bool(row['finite'] and len(y)==q.n_samples and row.get('zero_target_max_abs',0) in (None,0) and row.get('gain_relative_max_error',0)<=1e-12 and row.get('pitch_noise_max_error',0)==0)
   except Exception: row.update(status='failed',traceback=traceback.format_exc(),criteria_pass=False)
   rows.append(row)
summary={}
for name in cases:
 for method in ('v2','D'):
  rr=[r for r in rows if r['case']==name and r['method']==method and r['status']=='measured']
  ratios=[r['power_ratio'] for r in rr if r['power_ratio'] is not None]
  summary[name+'/'+method]={'outputs':len(rr),'all_criteria_pass':all(r['criteria_pass'] for r in rr),'mean_power_ratio':float(np.mean(ratios)) if ratios else None,'min_power_ratio':min(ratios) if ratios else None,'max_power_ratio':max(ratios) if ratios else None}
failures=sum(not r['criteria_pass'] for r in rows)+sum(r['absolute_error']>1e-12 for r in analytic)
result={'contract':contract,'finished_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'completed' if not failures else 'criteria_failed','failures':failures,'rows':rows,'analytic':analytic,'summary':summary,'limitations':['Synthetic noise-only control measurement, not human quality or MOS calibration.','Finite eight-seed power variation is reported, not thresholded.','Pitch noise invariance is appropriate: independent noise PSD remains fixed under pitch edit.','Time edits verify exact output length and absence of nonfinite samples; do not imply identical stochastic waveforms.']}
(OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'status':result['status'],'failures':failures,'outputs':len(rows),'analytic_cases':len(analytic),'summary':summary},ensure_ascii=False))
